### What would your feature do ?

Change `zod` validation of `output_is_list` to allows `object` type of unknown key.

https://github.com/Comfy-Org/ComfyUI_frontend/blob/c73915e31eaf2c549e4f4f6ec794561f00fb218a/src/types/apiTypes.ts#L330

Why? Many of the tricks used for dynamic input/output involving "wildcarding" the boolean portion of OUTPUT_IS_LIST, since we don't know how many output are created. Sample classes used:

```py
class WildDict(dict):
	def __init__(self, *args, **kwargs):
		self.update(*args, **kwargs)

	def __contains__(self, item):
		return True
	
	def __getitem__(self, key):
		return None

class TautologyStr(str):
	def __ne__(self, other):
		return False

class TautologyDictStr(dict):
	def __init__(self, *args, **kwargs):
		self.update(*args, **kwargs)

	def __getitem__(self, index):
		if isinstance(index, str) or isinstance(index, int):
			return TautologyStr("")
		return super().__getitem__(index)

class TautologyRest(tuple):
	def __iter__(self):
		yield False
		while True:
			yield True

	def __getitem__(self, index):
		if index == 0:
			return False
		return True

class ContradictRest(tuple):
	def __iter__(self):
		yield True
		while True:
			yield False

	def __getitem__(self, index):
		if index == 0:
			return True
		return False

class TautologyAll(tuple):
	def __iter__(self):
		while True:
			yield True

	def __getitem__(self, index):
		return True

class ContradictAll(tuple):
	def __iter__(self):
		while True:
			yield False

	def __getitem__(self, index):
		return False
```

Sample node:

```py
class StubNode:
	@classmethod
	def INPUT_TYPES(cls):
		return {
			"required": WildDict(),
			"hidden": {
				"_prompt": "PROMPT",
				"_id": "UNIQUE_ID",
				"_workflow": "EXTRA_PNGINFO"
			}
		}
	
	RETURN_TYPES = TautologyDictStr()
	INPUT_IS_LIST = True
	OUTPUT_IS_LIST = TautologyAll()
	FUNCTION = "execute"
	CATEGORY = "_for_testing"

	def execute(self, _id = None, _prompt = None, _workflow = None, **kwargs):
		pass
```

