    FUNCTION = "execute"
    CATEGORY = "FlowChain ⛓️"
    #OUTPUT_NODE = True

    @classmethod
    def IS_CHANGED(s, Name, type, default, **kwargs):
        m = hashlib.sha256()
        if default is not None:
            m.update(str(default).encode())
        else:
            m.update(Name.encode()+type.encode())
        return m.digest().hex()

